-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Checks travel action usability and detects changes to the cooldowns watched by the planner.

local Adapter = APR.NavigationAdapter
local Shared = APR.NavigationAdapter._helpers
local Call = Shared.Call
local Number = Shared.Number
local environment = Shared.environment

local function ReadActionUsability(kind, id, ignoreCooldown)
    if kind == "housing" then
        if not C_Housing or not Adapter:GetHousingData() then return false, "unknown" end
        if C_Housing.HasHousingExpansionAccess and Call(C_Housing.HasHousingExpansionAccess) ~= true then
            return false, "unavailable"
        end
        if C_Housing.IsHousingServiceEnabled and Call(C_Housing.IsHousingServiceEnabled) ~= true then
            return false, "unavailable"
        end
        local cooldown = Call(C_Housing.GetVisitCooldownInfo)
        if cooldown then
            if not Number(cooldown.startTime) or not Number(cooldown.duration) then return false, "restricted" end
            if cooldown.startTime + cooldown.duration > (GetTime and GetTime() or 0) then return false, "cooldown" end
        end
        if not Adapter:GetHousingPosition() then return false, "pending_data" end
        return true
    elseif kind == "housing_return" then
        local canReturn = Call(C_HousingNeighborhood and C_HousingNeighborhood.CanReturnAfterVisitingHouse)
        return canReturn == true, canReturn == nil and "pending_data" or nil
    end
    if not APR.GetRouteActionUsability then return false, "pending_data" end
    local usable, reason = Call(APR.GetRouteActionUsability, APR, kind, id, ignoreCooldown == true, true)
    if usable == nil then return false, "pending_data" end
    return usable == true, reason
end--[[APR_DIAG]]; ReadActionUsability = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterActions.lua:14:ReadActionUsability#1", ReadActionUsability)--[[/APR_DIAG]]

function environment.getActionUsabilityIgnoringCooldown(kind, id)
    return ReadActionUsability(kind, id, true)
end--[[APR_DIAG]]; environment.getActionUsabilityIgnoringCooldown = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterActions.lua:40:environment.getActionUsabilityIgnoringCooldown#2", environment.getActionUsabilityIgnoringCooldown)--[[/APR_DIAG]]

local watchedActions = {}

function environment.getActionUsability(kind, id)
    local usable, reason = ReadActionUsability(kind, id)
    -- Only actions the catalogue actually checked can affect this character's
    -- journey. Unknown spells and missing items change through collection or
    -- inventory events, so ordinary cooldown events need not revisit them.
    local key = kind .. ":" .. tostring(id)
    if usable or reason == "cooldown" or reason == "restricted" or reason == "pending_data" or reason == "unusable" then
        local watched = watchedActions[key]
        if not watched then
            watched = { kind = kind, id = id }
            watchedActions[key] = watched
        end
        -- UI checks must not consume a transition before the cooldown job can
        -- notice it. Only that job advances an existing observation's value.
        if not watched.enabled then
            watched.usable, watched.reason = usable, reason
        end
        watched.enabled = true
    else
        -- Keep existing keys stable while a check is suspended between frames.
        local watched = watchedActions[key]
        if watched then watched.enabled = false end
    end
    return usable, reason
end--[[APR_DIAG]]; environment.getActionUsability = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterActions.lua:46:environment.getActionUsability#3", environment.getActionUsability)--[[/APR_DIAG]]

local CooldownCheck = {}
CooldownCheck.__index = CooldownCheck

function CooldownCheck:Step(maxOperations, maxMilliseconds)
    local deadline = self.clock and (self.clock() + (maxMilliseconds or 0.5))
    for operation = 1, maxOperations or 8 do
        if operation > 1 and deadline and self.clock() >= deadline then return "planning" end
        local key, watched = next(watchedActions, self.cursor)
        self.cursor = key
        if not key then return "ready", self.changed == true end
        if watched.enabled then
            local usable, reason = ReadActionUsability(watched.kind, watched.id)
            if usable ~= watched.usable or reason ~= watched.reason then
                watched.usable, watched.reason = usable, reason
                -- Shared cooldowns can change several actions at once. Finish
                -- the bounded scan so one transition requests only one replan.
                self.changed = true
            end
        end
    end
    return "planning"
end--[[APR_DIAG]]; CooldownCheck.Step = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterActions.lua:75:CooldownCheck:Step#4", CooldownCheck.Step)--[[/APR_DIAG]]

function Adapter:CreateCooldownCheck()
    return setmetatable({ clock = debugprofilestop }, CooldownCheck)
end--[[APR_DIAG]]; Adapter.CreateCooldownCheck = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterActions.lua:95:Adapter:CreateCooldownCheck#5", Adapter.CreateCooldownCheck)--[[/APR_DIAG]]
